html:
{% set vat_rate = 0 %}

{% if doc.taxes and doc.taxes|length > 0 %}
    {% set vat_rate = frappe.utils.flt(doc.taxes[0].rate) %}
{% endif %}


<style>
    @page {
        size: A4;
        margin: 10mm 12mm 17mm 12mm;
    }

    * {
        box-sizing: border-box;
    }

    body,
    .print-format {
        font-family: Arial, Helvetica, sans-serif;
        font-size: 10px;
        color: #333;
        line-height: 1.35;
    }

    .quotation-container {
        width: 100%;
        min-height: 270mm;
        position: relative;
    }


    /* ==================================================
       LETTERHEAD — OLD IMAGE METHOD

       Kept commented for future use.
       ================================================== */

    /*.letterhead-table {*/
    /*    width: 100%;*/
    /*    border-collapse: collapse;*/
    /*    margin-bottom: 10px;*/
    /*}*/

    /*.letterhead-table td {*/
    /*    border: none !important;*/
    /*    padding: 0;*/
    /*    vertical-align: top;*/
    /*}*/

    /*.logo-cell {*/
    /*    width: 50%;*/
    /*    text-align: left;*/
    /*}*/

    /*.address-cell {*/
    /*    width: 50%;*/
    /*    text-align: right;*/
    /*}*/

    /*.logo-image {*/
    /*    width: 285px;*/
    /*    max-height: 85px;*/
    /*    object-fit: contain;*/
    /*    object-position: left top;*/
    /*}*/

    /*.address-image {*/
    /*    width: 260px;*/
    /*    max-height: 90px;*/
    /*    object-fit: contain;*/
    /*    object-position: right top;*/
    /*}*/


    /* ==================================================
       FIXED LETTERHEAD
       ================================================== */

    .hardcoded-letterhead {
        width: 100%;
        margin-bottom: 5px;
    }


    /* ==================================================
       DOCUMENT TITLE
       ================================================== */

    .document-heading-table {
        width: 100%;
        border-collapse: collapse;
        margin: 4px 0 22px;
    }

    .document-heading-table td {
        border: none !important;
        padding: 0;
        vertical-align: top;
    }

    .heading-empty-space {
        width: 55%;
    }

    .heading-section {
        width: 45%;
        text-align: right;
    }

    .document-title {
        margin: 0;
        color: #222;
        font-size: 29px;
        line-height: 1.1;
        font-weight: 500;
    }

    .document-number {
        margin-top: 3px;
        color: #333;
        font-size: 10px;
        font-weight: bold;
    }


    /* ==================================================
       CUSTOMER AND QUOTATION INFORMATION
       ================================================== */

    .information-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 20px;
    }

    .information-table td {
        border: none !important;
        padding: 0;
        vertical-align: top;
    }

    .customer-section {
        width: 55%;
        padding-right: 25px !important;
    }

    .quotation-info-section {
        width: 45%;
        padding-top: 55px !important;
    }

    .section-label {
        margin-bottom: 2px;
        color: #444;
        font-size: 10px;
    }

    .customer-name {
        margin-bottom: 2px;
        color: #222;
        font-size: 11px;
        font-weight: bold;
    }

    .customer-address {
        color: #333;
        font-size: 9.5px;
        line-height: 1.4;
    }

    .contact-details {
        margin-top: 10px;
        color: #333;
        font-size: 9.5px;
        line-height: 1.4;
    }

    .subject-section {
        margin-top: 20px;
        color: #333;
        font-size: 9.5px;
    }

    .subject-label {
        margin-bottom: 4px;
        font-weight: normal;
    }

    .subject-value {
        color: #222;
    }

    .quotation-details {
        width: 100%;
        border-collapse: collapse;
        font-size: 10px;
    }

    .quotation-details td {
        border: none !important;
        padding: 4px 4px;
        vertical-align: top;
    }

    .quotation-details .detail-label {
        width: 50%;
        text-align: right;
        color: #444;
    }

    .quotation-details .detail-value {
        width: 50%;
        text-align: right;
        color: #222;
    }


    /* ==================================================
       ITEM TABLE
       ================================================== */

    .item-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
        margin-bottom: 10px;
    }

    .item-table thead {
        display: table-header-group;
    }

    .item-table th {
        padding: 7px 6px;
        background: #333;
        color: white;
        border: none;
        font-size: 9.5px;
        font-weight: normal;
        vertical-align: middle;
    }

    .item-table td {
        padding: 9px 6px;
        vertical-align: top;
        border-top: none;
        border-left: none;
        border-right: none;
        border-bottom: 1px solid #ccc;
        font-size: 9px;
    }

    .item-table tbody tr:last-child td {
        padding-bottom: 12px;
    }

    .col-number {
        width: 5%;
        text-align: center;
    }

    .col-image {
        width: 12%;
        text-align: center;
    }

    .col-description {
        width: 48%;
        text-align: left;
    }

    .col-qty {
        width: 8%;
        text-align: center;
    }

    .col-rate {
        width: 13%;
        text-align: right;
    }

    .col-amount {
        width: 14%;
        text-align: right;
    }

    .item-image {
        width: 55px;
        height: 55px;
        max-width: 55px;
        max-height: 55px;
        object-fit: contain;
    }

    .item-image-placeholder {
        width: 50px;
        height: 50px;
        margin: auto;
        border: 1px solid #ddd;
        color: #aaa;
        font-size: 7px;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .item-name {
        margin-bottom: 2px;
        color: #222;
        font-size: 10px;
        font-weight: 600;
    }

    .item-code {
        margin-bottom: 2px;
        color: #555;
        font-size: 8.5px;
    }

    .item-description {
        color: #333;
        font-size: 8.5px;
        line-height: 1.45;
        word-break: break-word;
    }

    .item-reference {
        margin-top: 2px;
        color: #555;
        font-size: 8px;
        line-height: 1.4;
    }

    .quantity-uom {
        display: block;
        margin-top: 2px;
        color: #555;
        font-size: 8px;
    }


    /* ==================================================
       TOTALS
       ================================================== */

    .summary-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 4px;
        page-break-inside: avoid;
    }

    .summary-table td {
        border: none !important;
        padding: 0;
        vertical-align: top;
    }

    .summary-empty-section {
        width: 64%;
    }

    .totals-section {
        width: 36%;
    }

    .totals-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10px;
    }

    .totals-table td {
        border: none !important;
        padding: 8px 5px;
        vertical-align: top;
    }

    .totals-label {
        width: 58%;
        padding-right: 12px !important;
        text-align: right;
        color: #333;
    }

    .totals-value {
        width: 42%;
        text-align: right;
        color: #222;
        white-space: nowrap;
    }

    .vat-row td {
        border-top: 1px solid #eee !important;
    }

    .grand-total-row td {
        padding-top: 10px;
        border-top: 2px solid #222 !important;
        font-weight: bold;
    }

    .grand-total-label {
        font-size: 13px;
    }

    .grand-total-value {
        font-size: 13px;
        font-weight: bold;
    }


    /* ==================================================
       AMOUNT IN WORDS
       ================================================== */

    .amount-words-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 8px;
        page-break-inside: avoid;
    }

    .amount-words-table td {
        border: none !important;
        padding: 5px 0;
        vertical-align: top;
    }

    .amount-words-empty {
        width: 58%;
    }

    .amount-words-label {
        width: 16%;
        text-align: right;
        padding-right: 10px !important;
        color: #444;
    }

    .amount-words-value {
        width: 26%;
        color: #222;
        font-weight: bold;
        font-style: italic;
    }


    /* ==================================================
       CUSTOMER NOTES
       ================================================== */

    .customer-notes-section {
        margin-top: 35px;
        color: #333;
        font-size: 9px;
        page-break-inside: avoid;
    }

    .customer-notes-title {
        margin-bottom: 7px;
        color: #333;
        font-size: 11px;
        font-weight: 600;
    }

    .customer-notes-content {
        line-height: 1.45;
    }


    /* ==================================================
       TERMS AND CONDITIONS
       ================================================== */

    .terms-section {
        margin-top: 28px;
        color: #333;
        font-size: 9px;
        page-break-inside: avoid;
    }

    .terms-title {
        margin-bottom: 7px;
        color: #333;
        font-size: 11px;
        font-weight: 600;
    }

    .terms-content {
        line-height: 1.45;
    }

    .thank-you {
        margin-top: 15px;
    }

    .authorized-signature {
        margin-top: 15px;
    }


    /* ==================================================
       FOOTER
       ================================================== */

    .hardcoded-footer {
        width: 100%;
        margin-top: 25px;
        page-break-inside: avoid;
    }

    .brand-footer-image {
        width: 100%;
        max-height: 55px;
        object-fit: contain;
        object-position: center bottom;
    }


    /* ==================================================
       DRAFT WATERMARK
       ================================================== */

    .draft-watermark {
        position: fixed;
        top: 43%;
        left: 12%;
        width: 76%;
        z-index: -1;
        transform: rotate(-55deg);
        text-align: center;
        color: rgba(120, 120, 120, 0.13);
        font-size: 62px;
        font-weight: normal;
        white-space: nowrap;
    }


    /* ==================================================
       PAGE BREAKING
       ================================================== */

    .item-table tr {
        page-break-inside: avoid;
    }

    .summary-table,
    .amount-words-table,
    .customer-notes-section,
    .terms-section,
    .hardcoded-footer {
        page-break-inside: avoid;
    }

    @media print {
        body,
        .print-format {
            margin: 0;
            padding: 0;
        }

        .quotation-container {
            width: 100%;
        }
    }
</style>


<div class="quotation-container">


    <!-- ==================================================
         DRAFT WATERMARK

         Shows only when the Quotation is not submitted.
         ================================================== -->

    {% if doc.docstatus == 0 %}
        <div class="draft-watermark">
            Yet to be Approved
        </div>
    {% endif %}


    <!--
    To remove the watermark completely, comment the block above.

    To show the watermark always, use:

    <div class="draft-watermark">
        Yet to be Approved
    </div>
    -->


    <!-- ==================================================
         LETTERHEAD — OLD IMAGE METHOD

         Commented, not removed.
         ================================================== -->

    <!--
    <table class="letterhead-table">
        <tr>
            <td class="logo-cell">
                <img
                    src="/private/files/arabscale_logo.png"
                    class="logo-image"
                    alt="Arab Scale Trading"
                >
            </td>

            <td class="address-cell">
                <img
                    src="/private/files/arabscale_address.png"
                    class="address-image"
                    alt="Company Address"
                >
            </td>
        </tr>
    </table>
    -->


    <!-- ==================================================
         ACTIVE FIXED LETTERHEAD

         Same method used in Sales Invoice.
         ================================================== -->

    {% set fixed_letterhead = frappe.db.get_value(
        "Letter Head",
        "Arab Scale Letter Head - Standard",
        "content"
    ) %}

    {% if fixed_letterhead %}
        <div class="hardcoded-letterhead">
            {{ fixed_letterhead }}
        </div>
    {% endif %}


    <!-- ==================================================
         QUOTATION TITLE
         ================================================== -->

    <table class="document-heading-table">
        <tr>
            <td class="heading-empty-space"></td>

            <td class="heading-section">
                <h1 class="document-title">
                    Quotation
                </h1>

                <div class="document-number">
                    # {{ doc.name }}
                </div>
            </td>
        </tr>
    </table>


    <!-- ==================================================
         CUSTOMER AND QUOTATION INFORMATION
         ================================================== -->

    <table class="information-table">
        <tr>
            <td class="customer-section">

                <div class="section-label">
                    Bill to:
                </div>

                <div class="customer-name">
                    {{ doc.customer_name or doc.party_name }}
                </div>

                <div class="customer-address">
                    {% if doc.address_display %}
                        {{ doc.address_display }}
                    {% elif doc.customer_address %}
                        {{ doc.customer_address }}
                    {% endif %}
                </div>


                {% if doc.contact_display %}
                    <div class="contact-details">
                        {{ doc.contact_display }}
                    </div>
                {% endif %}


                {% if doc.contact_mobile %}
                    <div class="customer-address">
                        {{ doc.contact_mobile }}
                    </div>
                {% endif %}


                <!--
                Optional email address

                {% if doc.contact_email %}
                    <div class="customer-address">
                        {{ doc.contact_email }}
                    </div>
                {% endif %}
                -->


                <div class="subject-section">
                    <div class="subject-label">
                        Subject :
                    </div>

                    <div class="subject-value">
                        {{ doc.custom_subject or doc.order_type or "" }}
                    </div>
                </div>

            </td>


            <td class="quotation-info-section">

                <table class="quotation-details">

                    <tr>
                        <td class="detail-label">
                            Date :
                        </td>

                        <td class="detail-value">
                            {{ frappe.utils.formatdate(
                                doc.transaction_date,
                                "dd MMM yyyy"
                            ) }}
                        </td>
                    </tr>


                    <tr>
                        <td class="detail-label">
                            Sales person :
                        </td>

                        <td class="detail-value">
                            {% if doc.sales_team and doc.sales_team|length > 0 %}
                                {{ doc.sales_team[0].sales_person }}
                            {% else %}
                                {{ doc.sales_partner or "" }}
                            {% endif %}
                        </td>
                    </tr>


                    <!--
                    Optional Valid Till

                    {% if doc.valid_till %}
                        <tr>
                            <td class="detail-label">
                                Valid Till :
                            </td>

                            <td class="detail-value">
                                {{ frappe.utils.formatdate(
                                    doc.valid_till,
                                    "dd MMM yyyy"
                                ) }}
                            </td>
                        </tr>
                    {% endif %}
                    -->


                    <!--
                    Optional Customer Reference

                    {% if doc.customer_name %}
                        <tr>
                            <td class="detail-label">
                                Customer :
                            </td>

                            <td class="detail-value">
                                {{ doc.customer_name }}
                            </td>
                        </tr>
                    {% endif %}
                    -->

                </table>

            </td>
        </tr>
    </table>


    <!-- ==================================================
         ITEM TABLE
         ================================================== -->

    <table class="item-table">
        <thead>
            <tr>
                <th class="col-number">
                    S<br>N
                </th>

                <th class="col-image"></th>

                <th class="col-description">
                    Item &amp; Description
                </th>

                <th class="col-qty">
                    Qty
                </th>

                <th class="col-rate">
                    Rate in<br>
                    {{ doc.currency }}
                </th>

                <th class="col-amount">
                    Amount
                </th>
            </tr>
        </thead>

        <tbody>
            {% for item in doc.items %}

                {% set master_item_image = frappe.db.get_value(
                    "Item",
                    item.item_code,
                    "image"
                ) %}

                {% set display_image = item.image or master_item_image %}

                <tr>
                    <td class="col-number">
                        {{ loop.index }}
                    </td>


                    <td class="col-image">
                        {% if display_image %}
                            <img
                                src="{{ display_image }}"
                                class="item-image"
                                alt="{{ item.item_name or item.item_code }}"
                            >
                        {% else %}

                            <!--
                            No-image placeholder is currently hidden.

                            To show it, uncomment below:

                            <div class="item-image-placeholder">
                                No Image
                            </div>
                            -->

                        {% endif %}
                    </td>


                    <td class="col-description">

                        <div class="item-name">
                            {{ item.item_name or item.item_code }}
                        </div>


                        <!--
                        Item code is currently hidden.

                        To show the item code, uncomment below:

                        {% if item.item_code %}
                            <div class="item-code">
                                {{ item.item_code }}
                            </div>
                        {% endif %}
                        -->


                        {% if item.description %}
                            <div class="item-description">
                                {{ item.description }}
                            </div>
                        {% endif %}


                        {% if item.serial_no %}
                            <div class="item-reference">
                                Serial Number#:
                                {{ item.serial_no | replace("\n", ", ") }}
                            </div>
                        {% endif %}


                        {% if item.batch_no %}
                            <div class="item-reference">
                                Batch#:
                                {{ item.batch_no }}
                            </div>
                        {% endif %}


                        <!--
                        Optional Supplier Quotation Reference

                        {% if item.supplier_quotation %}
                            <div class="item-reference">
                                Supplier Quotation:
                                {{ item.supplier_quotation }}
                            </div>
                        {% endif %}
                        -->

                    </td>


                    <td class="col-qty">
                        {{ frappe.utils.fmt_money(
                            item.qty,
                            precision=2
                        ) }}

                        {% if item.uom %}
                            <span class="quantity-uom">
                                {{ item.uom }}
                            </span>
                        {% endif %}
                    </td>


                    <td class="col-rate">
                        {{ frappe.utils.fmt_money(
                            item.net_rate or item.rate,
                            precision=2
                        ) }}
                    </td>


                    <td class="col-amount">
                        {{ frappe.utils.fmt_money(
                            item.net_amount or item.amount,
                            precision=2
                        ) }}
                    </td>
                </tr>

            {% endfor %}
        </tbody>
    </table>


    <!-- ==================================================
         TOTALS
         ================================================== -->

    <table class="summary-table">
        <tr>
            <td class="summary-empty-section"></td>

            <td class="totals-section">

                <table class="totals-table">

                    <tr>
                        <td class="totals-label">
                            Sub Total
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.net_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>


                    {% if doc.discount_amount %}
                        <tr>
                            <td class="totals-label">
                                Discount
                            </td>

                            <td class="totals-value">
                                {{ frappe.utils.fmt_money(
                                    doc.discount_amount,
                                    precision=2
                                ) }}
                            </td>
                        </tr>
                    {% endif %}


                    <tr class="vat-row">
                        <td class="totals-label">
                            VAT
                            ({{ frappe.utils.fmt_money(
                                vat_rate,
                                precision=0
                            ) }}%)
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.total_taxes_and_charges or 0,
                                precision=2
                            ) }}
                        </td>
                    </tr>


                    <tr class="grand-total-row">
                        <td class="totals-label grand-total-label">
                            Total
                        </td>

                        <td class="totals-value grand-total-value">
                            {{ doc.currency }}
                            {{ frappe.utils.fmt_money(
                                doc.grand_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                </table>

            </td>
        </tr>
    </table>


    <!-- ==================================================
         TOTAL IN WORDS
         ================================================== -->

    <table class="amount-words-table">
        <tr>
            <td class="amount-words-empty"></td>

            <td class="amount-words-label">
                Total In Words:
            </td>

            <td class="amount-words-value">
                {{ doc.in_words or "" }}
            </td>
        </tr>
    </table>


    <!-- ==================================================
         CUSTOMER NOTES
         ================================================== -->

    <div class="customer-notes-section">

        <div class="customer-notes-title">
            Customer Notes
        </div>

        <div class="customer-notes-content">

            {% if doc.custom_customer_notes %}
                {{ doc.custom_customer_notes }}

            {% else %}

                <div style="margin-bottom:6px;">
                    Bank Details:
                </div>

                <div>
                    - Account Name: Arab Scale Trading LLC
                </div>

                <div>
                    - Account No.: 0024214538061
                </div>

                <div>
                    - IBAN No.: AE33 0400 0000 2421 4538 061
                </div>

                <div>
                    - Swift Code: NRAKAEAK
                </div>

                <div>
                    - Bank Name: National Bank of Ras Al-Khaimah
                </div>

                <div>
                    - Branch: Sharjah
                </div>

            {% endif %}

        </div>
    </div>


    <!--
    Alternative dynamic bank details

    Create a custom HTML field named:
    custom_customer_notes

    Then enter the bank details in each Quotation.

    The active code above already checks:
    {{ doc.custom_customer_notes }}
    -->


    <!-- ==================================================
         TERMS AND CONDITIONS
         ================================================== -->

    <div class="terms-section">

        <div class="terms-title">
            Terms &amp; Conditions:
        </div>

        <div class="terms-content">

            {% if doc.terms %}
                {{ doc.terms }}

            {% else %}

                <div>
                    Payment: 100% advance
                </div>

                <div>
                    Delivery: Ex-stock (subject to prior sale).
                </div>

                <div>
                    Warranty: 12 Months from the date of Invoice
                    (against any manufacturing defect)
                </div>

            {% endif %}

        </div>


        <div class="thank-you">
            We take this opportunity to thank you for your enquiry,
            if you have any query please feel free to contact us.
        </div>


        <div class="authorized-signature">
            For {{ doc.company }},
        </div>

    </div>


    <!-- ==================================================
         FOOTER — OPTION 1

         Get footer from the fixed Letter Head.
         ================================================== -->

    {% set fixed_footer = frappe.db.get_value(
        "Letter Head",
        "Arab Scale Letter Head - Standard",
        "footer"
    ) %}

    {% if fixed_footer %}
        <div class="hardcoded-footer">
            {{ fixed_footer }}
        </div>
    {% endif %}


    <!-- ==================================================
         FOOTER — OPTION 2

         Direct image method.
         Currently commented.
         ================================================== -->

    <!--
    <div class="hardcoded-footer">
        <img
            src="/private/files/arabscale_brand_logos.png"
            class="brand-footer-image"
            alt="Brands"
        >
    </div>
    -->


</div>
